-- Up Migration
-- Adds users.last_login_at and creates a trigger to keep it current.
-- Run the companion backfill script (scripts/backfill_last_login_at.py) after
-- applying this migration so historical data is populated.

-- 1. Add nullable column (metadata-only change, fast on Postgres)
ALTER TABLE users ADD COLUMN last_login_at timestamptz;

-- 2. Create trigger function that propagates new login events.
--    Uses GREATEST so the value never regresses if an older event is inserted.
CREATE OR REPLACE FUNCTION trg_update_user_last_login()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE users
    SET last_login_at = GREATEST(users.last_login_at, NEW.occurred_at)
    WHERE id = NEW.user_id;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 3. Attach trigger to login_events so every new insert updates the user row.
CREATE TRIGGER trg_login_events_update_last_login
    AFTER INSERT ON login_events
    FOR EACH ROW
    EXECUTE FUNCTION trg_update_user_last_login();

-- Down Migration
-- Reverses the schema changes.

